const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const blueLagoonPoint = ee.Geometry.Point(-22.4495, 63.8804); // Blue Lagoon, Iceland
    const reykjavikPoint = ee.Geometry.Point(-21.9426, 64.1466); // Reykjavík, Iceland

    // Create small buffers around the points for regional analysis
    const blueLagoon = blueLagoonPoint.buffer(1000); // 1 km radius
    const reykjavik = reykjavikPoint.buffer(2000); // 2 km radius for a city

    const date = '2024-11-24';
    // VIIRS DNB data is typically daily and represents night scenes.
    // The 'system:time_start' for a given day represents the beginning of the 24-hour UTC period.
    // For 4 AM local time (UTC+0), we're interested in data collected during the night covering this time.
    // Daily VIIRS DNB images are usually composite products for a specific night.
    // We'll filter for the date directly.
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG')
      .filterDate(startDate, endDate)
      .filterBounds(blueLagoon.centroid().union(reykjavik.centroid())); // Filter for images covering both areas

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log("No VIIRS DNB images found for November 24, 2024, in the region.");
      console.log("C1");
      return;
    }

    // Since we need to get data for a specific night, we'll take the first image if multiple exist
    // (e.g., if there are ascending/descending passes, but VCMCFG is a daily composite).
    const image = collection.first();

    // 3. Processing: Calculate average radiance for each location
    // Use a relatively coarse scale to avoid timeouts and for regional average.
    const scale = 500; // Meters, suitable for VIIRS DNB resolution (approx 750m at nadir)
    const bandName = 'avg_rad';

    // Function to calculate average radiance and valid pixel count
    const calculateRegionStats = async (geometry, name) => {
      const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      });

      const stats = await image.select(bandName).reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();

      const avgRad = stats[bandName];
      const pixelCount = stats[bandName + '_count'];

      return { avgRad, pixelCount, name };
    };

    const blueLagoonStats = await calculateRegionStats(blueLagoon, 'Blue Lagoon');
    const reykjavikStats = await calculateRegionStats(reykjavik, 'Reykjavík');

    console.log(`Blue Lagoon: Avg Radiance = ${blueLagoonStats.avgRad !== null ? blueLagoonStats.avgRad.toFixed(4) : 'N/A'}, Pixels = ${blueLagoonStats.pixelCount}`);
    console.log(`Reykjavík: Avg Radiance = ${reykjavikStats.avgRad !== null ? reykjavikStats.avgRad.toFixed(4) : 'N/A'}, Pixels = ${reykjavikStats.pixelCount}`);

    // 4. Validation & Final Answer
    if (blueLagoonStats.pixelCount === 0 || reykjavikStats.pixelCount === 0) {
      console.log("No valid pixels remaining after processing for one or both locations.");
      console.log("C2");
      return;
    }

    if (blueLagoonStats.avgRad === null || isNaN(blueLagoonStats.avgRad) ||
        reykjavikStats.avgRad === null || isNaN(reykjavikStats.avgRad)) {
      console.log("Calculation resulted in None/NaN for one or both locations.");
      console.log("C3");
      return;
    }

    if (blueLagoonStats.avgRad > reykjavikStats.avgRad) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    console.log("D"); // Indicate a general error or specific error type if possible
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
